    # last-time of each undirected pair up to now handled by scanning
    # build adjacency times
    adj={}
    pairtimes={}
    for u,v,t in evs:
        pairtimes.setdefault(frozenset((u,v)),[]).append(t)
        adj.setdefault(u,[]).append((v,t)); adj.setdefault(v,[]).append((u,t))
    res=[]
    for u,v,t3 in evs:
        # find common contact c with edges (u,c,t1),(v,c,t2) both <= t3 and t3-max<=delta
        best=None
        for c,t1 in adj.get(u,[]):
            if c==v or t1>t3: continue
            for c2,t2 in adj.get(v,[]):
                if c2!=c or t2>t3: continue
                m=max(t1,t2)
                if 0<=t3-m<=delta:
                    res.append((u,v,t3,c,t1,t2,t3-m))
    return res

