def closure_lags(evs):
    adj={}
    for u,v,t in evs:
        adj.setdefault(u,[]).append((v,t)); adj.setdefault(v,[]).append((u,t))
    lags=[]; candlags=[]
    for u,v,t3 in evs:
        du={}
        for c,t1 in adj.get(u,[]):
            if c!=v and t1<=t3 and (c not in du or t1>du[c]): du[c]=t1
        for c,t2 in adj.get(v,[]):
            if c in du and t2<=t3:
                lag=t3-max(du[c],t2)
                lags.append(lag)
                if u in cand or v in cand or c in cand: candlags.append(lag)
    return lags,candlags

